---- C: compile first, then run ----
/* hello.c */
#include <stdio.h>
int main(void) {
    printf("Hello\n");
    return 0;
}
$ gcc hello.c -o hello      # compiler makes a machine-code file
$ ./hello                   # the CPU runs that file directly

---- Python: run the source directly ----
# hello.py
print("Hello")
$ python hello.py           # interpreter reads and runs it each time

---- Which CPU architecture is this? ----
$ uname -m                  # x86_64 on most servers, arm64 on Apple Silicon, aarch64 on ARM Linux
$ python -c "import platform; print(platform.machine())"   # same answer from Python

$ ./routeplan               # an ARM64 binary copied to an x86_64 server
exec format error
$ docker build --platform linux/amd64 -t routeplan .   # build for the server's chip
